const topWnd = this.aras.getMostTopWindowWithAras(window);
const itName = this.aras.getItemProperty(topWnd.item, 'application');

if (this.aras.isNew(topWnd.item) || !itName) {
	const message = this.aras.getResource('../Modules/aras.innovator.TDF', 'documenttype.fill_app_and_save');
	this.aras.AlertWarning(message);
} else {
	this.showClassStructureDialog(this.aras.getItemTypeForClient(itName, 'name').node, 'classification', 'classification', `${propertyName}_D`, relationshipID);
}

return false;
